<style>.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:18px}.summary article{padding:14px;border:1px solid var(--line);border-radius:10px;background:#fff}.summary b{display:block;font-size:23px}.summary span{color:var(--muted);font-size:12px}.toolbar{display:flex;justify-content:space-between;gap:12px;margin-bottom:12px}.toolbar input{width:min(360px,100%);min-height:40px;padding:8px 11px;border:1px solid var(--line);border-radius:8px}.filters{display:flex;gap:7px;flex-wrap:wrap}.filters button,.filters a,.guide-button{min-height:36px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);font-weight:700;cursor:pointer;text-decoration:none}.filters button.active,.filters a.active{border-color:var(--blue);background:#eaf0ff;color:var(--blue)}.config-tabs-row{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.guide-button{display:inline-flex;align-items:center;gap:6px;background:var(--blue);border-color:var(--blue);color:#fff}.guide-button .icon{font-size:17px}.company-list{display:grid;gap:9px;min-height:260px;max-height:calc(100vh - 440px);overflow:auto;padding-right:4px;overscroll-behavior:contain}.company-list--compact{min-height:0;max-height:none;overflow:visible}.company{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px;border:1px solid var(--line);border-radius:10px;background:#fff;text-align:left;cursor:pointer}.company h2{margin:0;font-size:15px}.company-copy{min-width:0}.company-meta{display:flex;flex-wrap:wrap;gap:5px 16px;margin-top:5px;color:var(--muted);font-size:12px}.company-meta span{white-space:nowrap}.company-meta b{margin-right:4px;color:#526681;font-size:10px;font-weight:800;letter-spacing:.35px;text-transform:uppercase}.badge{padding:5px 9px;border-radius:999px;font-size:12px;font-weight:800;white-space:nowrap}.status--active .badge{background:var(--oksoft);color:var(--ok)}.status--inactive .badge,.status--unconfigured .badge{background:var(--warnsoft);color:var(--warn)}.empty{padding:16px;color:var(--muted)}dialog{width:min(780px,calc(100vw - 28px));max-height:calc(100vh - 28px);border:0;border-radius:13px;padding:0;color:var(--ink);box-shadow:0 18px 48px #0004}dialog::backdrop{background:#082b568a}.dialog-head{display:flex;justify-content:space-between;gap:12px;padding:18px 20px;border-bottom:1px solid var(--line)}.dialog-head h2{margin:0;font-size:18px}.dialog-head button{border:0;background:none;font-size:25px;cursor:pointer}.dialog-content{padding:18px 20px}.guide{color:var(--blue);font-weight:700}.dialog-content img{display:block;max-width:100%;margin-top:14px;border:1px solid var(--line);border-radius:8px}@media(max-width:700px){.summary{grid-template-columns:1fr}.toolbar{align-items:stretch;flex-direction:column}.config-tabs-row{align-items:flex-start;flex-direction:column}.company-list{max-height:calc(100vh - 510px)}.company{align-items:flex-start;flex-direction:column}.badge{white-space:normal}}</style>
<header class="page-head"><div><p class="eyebrow">Reforma Tributária</p><h1>Configurações fiscais</h1><p>Consulte CFOP, NCM e o preenchimento automático por empresa.</p></div></header>
<section class="panel"><div class="config-tabs-row"><nav class="filters" aria-label="Tipo de configuração"><a href="configuracoes-fiscais-view.php?aba=cfop">CFOP</a><a href="configuracoes-fiscais-view.php?aba=ncm">NCM</a><a class="active" href="configuracao-empresa-view.php" aria-current="page">Empresa</a></nav><button class="guide-button" id="guide-open" type="button"><span class="icon" aria-hidden="true">edit_location_alt</span>Onde alterar</button></div><section class="summary" id="summary" aria-live="polite"></section><div class="toolbar"><div class="filters" aria-label="Filtro de status"><button class="active" data-filter="all" type="button">Todas</button><button data-filter="active" type="button">Automático ativado</button><button data-filter="inactive" type="button">Manual/desativado</button><button data-filter="unconfigured" type="button">Não configurado</button></div><input id="search" type="search" placeholder="Buscar empresa"></div><div id="companies" class="company-list" aria-live="polite"></div></section>
