<script>const endpoint=<?= json_encode(reforma_tributaria_url('configuracao-empresa.php'),JSON_UNESCAPED_SLASHES) ?>, companies=document.querySelector('#companies'),summary=document.querySelector('#summary'),search=document.querySelector('#search'),dialog=document.querySelector('#detail');let rows=[],filter='all';const esc=x=>String(x??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));function key(x){return x.status.class==='status--active'?'active':x.status.class==='status--inactive'?'inactive':'unconfigured'}function draw(){const q=search.value.toLowerCase();const shown=rows.filter(x=>(filter==='all'||key(x)===filter)&&`${x.short_name||x.company_name}`.toLowerCase().includes(q));companies.classList.toggle('company-list--compact',shown.length<4);companies.innerHTML=shown.length?shown.map((x,i)=>`<button class="company ${esc(x.status.class)}" data-i="${rows.indexOf(x)}" type="button"><span class="company-copy"><h2>${esc(x.short_name||x.company_name)}</h2><span class="company-meta"><span><b>CNPJ</b>${esc(x.cnpj||'Não informado')}</span><span><b>Regime</b>${esc(x.tax_regime||'Não informado')}</span></span></span><span class="badge">${esc(x.status.title)}</span></button>`).join(''):'<p class="empty">Nenhuma empresa encontrada.</p>';companies.querySelectorAll('button').forEach(b=>b.onclick=()=>{const x=rows[Number(b.dataset.i)];document.querySelector('#detail-title').textContent=x.short_name||x.company_name;document.querySelector('#detail-status').textContent=x.status.description;dialog.showModal()})}fetch(endpoint,{credentials:'same-origin'}).then(r=>r.json()).then(data=>{if(data.error)throw Error(data.error);rows=data.companies||[];const s=data.summary||{};summary.innerHTML=`<article><b>${s.active||0}</b><span>Automático ativado</span></article><article><b>${s.inactive||0}</b><span>Manual/desativado</span></article><article><b>${s.unconfigured||0}</b><span>Não configurado</span></article>`;draw()}).catch(()=>companies.innerHTML='<p class="empty">Não foi possível carregar as empresas agora.</p>');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));draw()});search.oninput=draw;document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#guide-open').onclick=()=>{document.querySelector('#detail-title').textContent='Onde alterar esta configuração';document.querySelector('#detail-status').textContent='';dialog.showModal()}</script>
